"Abstand Anfang / Ende macht aus der Lasche eine Teillasche. Weitere geschlossene Profile in der Skizze werden zu Ausschnitten in der Platte. Bohrungen und Fenster in einer Lasche: Mitte entlang der Kante (bei einer gebogenen Kante entlang des Bogens), Mitte ab Ende der Biegung, Größe – sie erscheinen auch in der Abwicklung. Geht eine gebogene Kante ohne Knick in ihre Nachbarkante über und haben beide eine Lasche mit gleichem Biegewinkel, laufen die Laschen ohne Freischnitt ineinander über. „Kontur aus Skizze“ schneidet die geschlossenen Profile einer Skizze aus der Lasche: ihr X läuft entlang der Kante, ihr Y in die Lasche hinein, der Nullpunkt liegt am Kantenanfang auf dem Ende der Biegung (verschiebbar).":"Attālums no sākuma / beigām padara atloku par daļēju atloku. Citi slēgti profili skicē kļūst par izgriezumiem plāksnē. Caurumi un logi atlokā: centrs gar malu (liektai malai – gar loku), centrs no locījuma beigām, izmērs – tie parādās arī izklājumā. Ja liekta mala bez lauzuma pāriet blakus malā un abām ir atloks ar vienādu locījuma leņķi, atloki pāriet viens otrā bez atslodzes izgriezuma. „Kontūra no skices” izgriež skices slēgtos profilus no atloka: tās X iet gar malu, tās Y atloka iekšpusē, nullpunkts atrodas malas sākumā locījuma beigās (pārbīdāms).",
