"Alle Flächen wählen, die verschwinden sollen (bei einer Tasche Wände und Boden, bei einer Bohrung die Wand, bei einer Verrundung die Rundung). Die Nachbarflächen werden über die Lücke verlängert. Der Schritt rechnet bei Änderungen am Körper mit; beim ersten Mal lädt dafür der große Geometriekern (einige Sekunden).":"Izvēlieties visas skaldnes, kurām jāizzūd (kabatai – sienas un dibenu, caurumam – sienu, noapaļojumam – noapaļoto skaldni). Kaimiņu skaldnes tiek pagarinātas pāri spraugai. Solis tiek pārrēķināts, mainoties ķermenim; pirmo reizi tam tiek ielādēts pilnais ģeometrijas kodols (dažas sekundes).",
