"Bei „Bohrungen“ liegt das Teil auf der Fläche an dem Ende der Bohrung, das näher am Klickpunkt liegt. Mehrere Bohrungen nacheinander anklicken, dann „Fertig“.":"Izvēloties „Caurumi“, detaļa balstās uz skaldnes pie cauruma gala, kas ir tuvāk klikšķa punktam. Noklikšķiniet uz vairākiem caurumiem pēc kārtas, pēc tam uz „Gatavs“.",
"Bei „Bohrungen“ sitzt das Teil bündig in dem Ende der Bohrung, das näher am Klickpunkt liegt. Mehrere Bohrungen nacheinander anklicken, dann „Fertig“.":"Izvēloties „Caurumi“, detaļa atrodas vienā līmenī ar to cauruma galu, kas ir tuvāk klikšķa punktam. Noklikšķiniet uz vairākiem caurumiem pēc kārtas, pēc tam uz „Gatavs“.",
"Bei „Bohrungen“ sitzt der Kopf auf der Seite der Bohrung, die näher am Klickpunkt liegt; der Schaft zeigt in die Bohrung. Mehrere Bohrungen nacheinander anklicken, dann „Fertig“.":"Izvēloties „Caurumi“, galva atrodas cauruma pusē, kas ir tuvāk klikšķa punktam; kāts vērsts caurumā. Noklikšķiniet uz vairākiem caurumiem pēc kārtas, pēc tam uz „Gatavs“.",
