"Darstellungsqualität":"Attēlojuma kvalitāte",
"Das Bild konnte nicht gelesen werden.":"Attēlu nevarēja nolasīt.",
"Das Bild liegt als Vorlage auf der Ebene. Größe, Lage, Drehung und Deckkraft danach im Eigenschaftenfenster einstellen (z. B. Breite nach einer bekannten Abmessung).":"Attēls atrodas uz plaknes kā šablons. Pēc tam izmēru, atrašanās vietu, pagriezienu un necaurredzamību iestatiet īpašību logā (piem., platumu pēc zināma izmēra).",
"Das Ergebnis des Geometriekerns ist unlesbar":"Ģeometrijas kodola rezultāts nav nolasāms",
"Das Ergebnis konnte nicht geschrieben werden":"Rezultātu neizdevās ierakstīt",
"Das Maß muss größer als 0 sein.":"Izmēram jābūt lielākam par 0.",
"Das Netz bleibt ein Dreiecksnetz (kein B-Rep). Bearbeiten unter NETZ: Reparieren, Reduzieren, Glätten, Ebenenschnitt … 3D-Frässtrategien in der Fertigung können es direkt bearbeiten.":"Tīkls paliek trijstūru tīkls (nav B-Rep). Rediģēšana sadaļā TĪKLS: labot, samazināt, izlīdzināt, plaknes griezums … 3D frēzēšanas stratēģijas sadaļā Ražošana var to apstrādāt tieši.",
"Das Netz hat {0} Dreiecke. Jedes wird eine Fläche des Körpers – das dauert lange und macht den Körper träge. Vorher „Reduzieren“ ist meist besser.\n\nTrotzdem umwandeln?":"Tīklam ir {0} trijstūri. Katrs kļūs par ķermeņa skaldni – tas ilgst ilgi un padara ķermeni gausu. Parasti labāk vispirms „Samazināt”.\n\nTomēr pārveidot?",
"Das Netz ist nicht geschlossen. Zuerst „Reparieren“ ausführen – ein Körper braucht eine geschlossene Hülle.":"Tīkls nav slēgts. Vispirms izpildiet „Labot” – ķermenim nepieciešams slēgts apvalks.",
"Das Netz reicht in Z von {0} bis {1} mm, in X von {2} bis {3} mm, in Y von {4} bis {5} mm. Punkte, die weniger als die Toleranz von einer Geraden abweichen, entfallen.":"Tīkls stiepjas Z virzienā no {0} līdz {1} mm, X virzienā no {2} līdz {3} mm, Y virzienā no {4} līdz {5} mm. Punkti, kas no taisnes novirzās mazāk par pielaidi, tiek izlaisti.",
"Das Profil darf die Achse nicht schneiden. Eine offene Linie in der Skizze kann als Achse dienen.":"Profils nedrīkst krustot asi. Par asi var kalpot atvērta līnija skicē.",
"Das Profil mit den jetzigen Werten überschreiben":"Pārrakstīt profilu ar pašreizējām vērtībām",
"Das Profil wird entlang einer Linie/eines Linienzugs geführt. Profil am besten senkrecht zum Pfadanfang zeichnen (z. B. Profil auf XZ, Pfad auf XY).":"Profils tiek vadīts pa līniju/lauztu līniju. Profilu vislabāk zīmēt perpendikulāri ceļa sākumam (piem., profils uz XZ, ceļš uz XY).",
"Das Profil wird von der Skizzenebene aus erhaben oder vertieft geprägt.":"Profils tiek izcelts vai iespiests, sākot no skices plaknes.",
"Das Rohteil ist der Quader um den gewählten Körper (plus Versatz).":"Sagatave ir kvadrs ap izvēlēto ķermeni (plus nobīde).",
"Das Setup hat keine Operationen.":"Uzstādīšanā nav operāciju.",
"Das Werkzeug fräst in Kreisen, deren Mitte entlang der Nut wandert. Es ist nie über die volle Breite im Eingriff – das erlaubt große Zustelltiefen und schont Fräser und Spindel. Der Fräser sollte etwa 60 % der Nutbreite haben.":"Instruments frēzē apļos, kuru centrs pārvietojas gar rievu. Tas nekad nav ieejā ar pilnu platumu – tas ļauj lielus griešanas dziļumus un saudzē frēzi un vārpstu. Frēzei jābūt aptuveni 60 % no rievas platuma.",
"Das Werkzeug schneidet die Fläche nicht":"Instruments nekrusto virsmu",
"Das Werkzeug schneidet in Richtung der ausgewählten Flächen, bis es die angegebenen Aufmaße erreicht.":"Instruments griež izvēlēto skaldņu virzienā, līdz sasniedz norādītās piedevas.",
"Das Werkzeug taucht wie ein Bohrer senkrecht ein, Reihe für Reihe, bis auf das Modell plus Aufmaß. Die Schnittkraft wirkt entlang der Spindel: geeignet für lange Werkzeuge, tiefe Kavitäten und wenig steife Maschinen. Das Werkzeug muss über die Mitte schneiden.{0}":"Instruments iegrimst vertikāli kā urbis, rindu pa rindai, līdz modelim plus piedevai. Griešanas spēks darbojas gar vārpstu: piemērots gariem instrumentiem, dziļām dobumiem un mazāk stingrām iekārtām. Instrumentam jāgriež pāri centram.{0}",
"Das Werkzeug vermeidet diese Flächen unter Berücksichtigung der angegebenen Sicherheitsabstände (Spanner, Schraubstock).":"Instruments izvairās no šīm skaldnēm, ievērojot norādītos drošības attālumus (spīles, skrūvspīles).",
"Das Werkzeug vermeidet diese Flächen, während es in der Nähe liegende Flächen bearbeitet, und hält die Sicherheitsabstände ein.":"Instruments izvairās no šīm skaldnēm, apstrādājot tuvumā esošas skaldnes, un ievēro drošības attālumus.",
"Das erste Esc bricht nur das Werkzeug oder die Auswahl ab – ein Esc zu viel schließt die Skizze nicht":"Pirmais Esc atceļ tikai instrumentu vai izvēli – lieks Esc neaizver skici",
"Das ist keine Bohrung (Verrundung oder Zapfen) – bitte die Innenwand einer Bohrung anklicken.":"Tas nav caurums (noapaļojums vai tapa) – lūdzu, uzklikšķiniet uz cauruma iekšējās sieniņas.",
"Das ist keine Bohrung (Zylinderfläche) – bitte die Bohrungswand anklicken.":"Tas nav caurums (cilindriska virsma) – lūdzu, uzklikšķiniet uz cauruma sieniņas.",
"Das ist keine WerkFab-Design-Datei.":"Šis nav WerkFab dizaina fails.",
"Das ist keine schräge Kante – beide Enden der Fasenkante anklicken.":"Šī nav slīpa mala – noklikšķiniet uz abiem nošķēluma malas galiem.",
