"Dreh-Setup mit Fräs-Postprozessor – bitte einen Dreh-Postprozessor wählen.":"Virpošanas uzstādīšana ar frēzēšanas postprocesoru – lūdzu, izvēlieties virpošanas postprocesoru.",
