"Drehen: Das Teil muss rotationssymmetrisch um die Z-Achse liegen. Z0 = Planfläche oben, X = Durchmesser.":"Virpošana: detaļai jābūt rotācijas simetriskai ap Z asi. Z0 = gala virsma augšā, X = diametrs.",
"Drehen: Drehpunkt anklicken, dann den Winkel mit der Maus zeigen (Vorschau). Esc beendet.":"Griešana: noklikšķiniet uz griešanas punkta, pēc tam ar peli norādiet leņķi (priekšskatījums). Esc beidz.",
"Drehen: Durchmesser, auf dem der Revolver schaltet (Okuma, LinuxCNC). 0 = Rohteil-Ø + 200 mm":"Virpošana: diametrs, kurā revolvergalva pagriežas (Okuma, LinuxCNC). 0 = sagataves Ø + 200 mm",
