"Eigene Maße und Hinweise lassen sich im Blatt mit der Maus ziehen (Abstand der Maßlinie, Winkel der Hinweislinie, Radius des Winkelbogens). Zwei Ecken anklicken = Längenmaß. Einen Kreisrand in der Draufsicht anklicken = Durchmesser (bzw. Radius). Winkel: erst die Ecke, dann je einen Eckpunkt auf beiden Schenkeln. Fase: beide Enden der schrägen Kante – ergibt z. B. 2×45°. Im Textfeld hinter jedem Maß steht ein Zusatz wie ±0,1, H7 oder 4×.":"Savus izmērus un piezīmes lapā var vilkt ar peli (izmēra līnijas attālums, norādes līnijas leņķis, leņķa loka rādiuss). Divi noklikšķināti stūri = garuma izmērs. Apļa mala virsskatā = diametrs (vai rādiuss). Leņķis: vispirms virsotne, tad pa punktam uz abām malām. Nošķēlums: abi slīpās malas gali – iznākums, piem., 2×45°. Teksta laukā aiz katra izmēra ir papildinājums, piemēram, ±0,1, H7 vai 4×.",
