"Ein runder Fräser lässt in jeder Innenecke seinen Radius stehen – ein eckiges Gegenstück passt dann nicht hinein. Der Freistich fährt an jeder scharfen Innenecke kurz in die Ecke und zurück.{0}{1}":"Apaļa frēze katrā iekšējā stūrī atstāj savu rādiusu – stūrains pretdetaļas elements tad neiekļaujas. Izgriezums pie katra asā iekšējā stūra īsi ieiet stūrī un atpakaļ.{0}{1}",
