"Erhebung braucht zwei Skizzen mit je einer Kurve (auf verschiedenen Ebenen).":"Loft nepieciešamas divas skices ar vienu līkni katrā (dažādās plaknēs).",
"Erhebung nicht möglich – Querschnitte prüfen (je ein geschlossenes Profil, nicht verdreht)":"Loft nav iespējams – pārbaudiet šķērsgriezumus (katrā viens slēgts profils, bez sagriešanās)",
"Erhebung nicht möglich – je Skizze eine Kurve, gleiche Richtung, nicht verdreht":"Loft nav iespējams – katrā skicē viena līkne, vienāds virziens, bez sagriešanās",
"Ersetzt den Standard-Kurzbefehl „{0}“.":"Aizstāj noklusējuma īsinājumtaustiņu „{0}“.",
"Erst die Fläche an dem Körper anklicken, der bewegt wird, dann die Zielfläche am anderen Körper. Der Körper wird gedreht und verschoben, bis der erste Klickpunkt auf dem zweiten liegt und die Flächen aufeinander liegen.":"Vispirms uzklikšķiniet uz skaldnes ķermenim, kas tiek pārvietots, pēc tam uz mērķa skaldnes otram ķermenim. Ķermenis tiek pagriezts un pārvietots, līdz pirmais klikšķa punkts atrodas uz otrā un skaldnes gulst vienu uz otras.",
"Erst die Kante an dem Körper anklicken, der bewegt wird, dann die Zielkante am anderen Körper. Gerade Kanten kommen deckungsgleich aufeinander (Mitte auf Mitte); bei Kreiskanten – Bohrung und Zapfen – werden die Achsen gleich gerichtet und die Mittelpunkte zusammengelegt.":"Vispirms uzklikšķiniet uz malas ķermenim, kas tiek pārvietots, pēc tam uz mērķa malas otram ķermenim. Taisnās malas sakrīt (vidus uz vidu); apļveida malām – caurumam un tapai – asis tiek vērstas vienādi un centra punkti savietoti.",
"Erst ein Setup anlegen.":"Vispirms izveidojiet uzstādīšanu.",
"Erst ein Setup mit Operationen anlegen.":"Vispirms izveidojiet uzstādīšanu ar operācijām.",
"Erst eine Skizze oder Konstruktionsebene wählen – dann schaut Strg+8 senkrecht darauf.":"Vispirms izvēlieties skici vai konstrukcijas plakni – tad Ctrl+8 skatās uz to perpendikulāri.",
"Erst einen Körper in KONSTRUKTION erstellen oder ein Netz (STL) einfügen.":"Vispirms izveidojiet ķermeni sadaļā KONSTRUĒŠANA vai ievietojiet tīklu (STL).",
"Erst einen Körper in KONSTRUKTION erstellen.":"Vispirms izveidojiet ķermeni sadaļā KONSTRUĒŠANA.",
"Erst einen Namen für das Profil eingeben.":"Vispirms ievadiet profila nosaukumu.",
"Erst in eine Vorlage klicken, dann den Platzhalter wählen":"Vispirms noklikšķiniet sablonā, pēc tam izvēlieties vietturi",
"Erste Ecke klicken, dann gegenüberliegende Ecke.":"Noklikšķiniet uz pirmā stūra, pēc tam uz pretējā stūra.",
