"Fläche eines Körpers anklicken: ihr Rand kommt als Kontur in die Skizze. Eine Kante anklicken projiziert nur diese Kante (Kreise bleiben Kreise). Projizierte Geometrie ist violett.":"Noklikšķiniet uz ķermeņa skaldnes: tās mala tiek pievienota skicei kā kontūra. Klikšķis uz malas projicē tikai šo malu (riņķi paliek riņķi). Projicētā ģeometrija ir violeta.",
"Fläche ersetzen":"Aizstāt skaldni",
"Fläche ersetzen: eine ebene Fläche auf eine andere Ebene legen – der Körper wächst oder wird gekürzt":"Aizstāt skaldni: novietot plakanu skaldni uz citas plaknes – ķermenis kļūst lielāks vai īsāks",
