"Flächen am Körper":"Ķermeņa skaldnes",
"Flächen am Teilende (Zweiflach, Vierkant, Sechskant) mit einem angetriebenen Schaftfräser entlang Z. Schlüsselweite = doppelter Abstand der Fläche von der Drehachse. X und C fahren gemeinsam (Polar-Interpolation, Fanuc G12.1); ohne diese Vorlage im Postprozessor werden kurze X/C-Schritte ausgegeben.":"Skaldnes detaļas galā (divas skaldnes, kvadrāts, sešstūris) ar dzīvo kātfrēzi gar Z. Atslēgas platums = divkāršs skaldnes attālums no griešanās ass. X un C kustas kopā (polārā interpolācija, Fanuc G12.1); ja postprocesorā nav šīs veidnes, tiek izvadīti īsi X/C soļi.",
"Flächen anklicken, die aufgedickt werden (erneut klicken entfernt).":"Noklikšķiniet uz skaldnēm, kas tiks sabiezinātas (atkārtots klikšķis noņem).",
