"Fusion-360-Postprozessor „{0}“ übernommen:\n\n• {1}":"Fusion 360 postprocesors „{0}” pārņemts:\n\n• {1}",
"Fährt alle scharfen Außenkanten ab, die von oben erreichbar sind, und bricht sie um die Entgrattiefe – mit dem Fasenfräser als Fase (Werkzeugachse senkrecht, Spitze außerhalb der Kante), mit dem Kugel-/Lollipop-Fräser gerundet.":"Izbrauc visas asās ārējās malas, kurām var piekļūt no augšas, un nolauž tās par notīrīšanas dziļumu – ar nošķēlumu frēzi kā nošķēlumu (instrumenta ass vertikāla, gals ārpus malas), ar lodveida/lollipop frēzi noapaļojot.",
