"Gerade Linien der Skizze, die zu keinem Profil gehören (auch Hilfslinien). Biegung: die Linie ist die Mitte der Biegezone, die Skizze dort der Zuschnitt – das größte Stück der Platte bleibt liegen, alles jenseits der Linie schwenkt mit seinen Laschen mit. Die Linie gilt über die ganze Platte. Sicke: eine Rippe entlang der Linie, im Querschnitt und an den Enden rund; das Blech behält seine Dicke.":"Skices taisnās līnijas, kas nepieder nevienam profilam (arī palīglīnijas). Liekums: līnija ir liekuma zonas vidus, un skice tur ir sagatave – lielākais plātnes gabals paliek vietā, viss aiz līnijas pagriežas kopā ar saviem atlokiem. Līnija attiecas uz visu plātni. Rievojums: ribas veida izcilnis gar līniju, šķērsgriezumā un galos noapaļots; skārds saglabā savu biezumu.",
