"Geschlossen: Laschen an zwei Nachbarkanten laufen bis zur Winkelhalbierenden der Ecke und lassen dort den Spalt frei. Die Eckfreistellung sitzt, wo sich die Biegezonen kreuzen – in der Abwicklung und im gebogenen Teil. Auch eine Lasche an einer gebogenen Kante wird an einer echten Ecke auf Gehrung geschnitten (dort ohne Eckfreistellung).":"Slēgts: atloki uz divām blakus esošām malām iet līdz stūra bisektrisei un atstāj tur spraugu. Stūra atbrīvojums atrodas tur, kur krustojas liekuma zonas – izklājumā un saliektajā detaļā. Arī atloks uz izliektas malas īstā stūrī tiek griezts slīpi (tur bez stūra atbrīvojuma).",
