"Je Skizze die erste Kurve – offen oder geschlossen. Die Kurven werden mit einer Haut verbunden (Fläche ohne Dicke).":"No katras skices pirmā līkne – atvērta vai slēgta. Līknes tiek savienotas ar apvalku (virsma bez biezuma).",
"Je Tafel eine Datei. Die Bahn läuft um die halbe Schnittfuge (beim Fräsen den halben Fräser) neben dem Umriss im Abfall; Ausschnitte kommen vor dem Umriss ihres Teils, jede Kontur beginnt mit einem Anschnitt aus dem Abfall. Einschalten mit M3 (Laser: M3 S…), Ausschalten mit M5, Einstechzeit als G4. Nullpunkt ist die linke untere Ecke der Tafel, beim Fräsen Z0 die Blechoberseite. Das Programm vor dem Einsatz an der Maschine oder in einem NC-Simulator prüfen.":"Katrai loksnei viens fails. Trajektorija iet pusi griezuma platuma (frēzējot – pusi frēzes) blakus kontūrai atkritumos; izgriezumi tiek pirms savas detaļas ārējās kontūras, katra kontūra sākas ar iegriešanos no atkritumiem. Ieslēgšana ar M3 (lāzers: M3 S…), izslēgšana ar M5, caurduršanas laiks kā G4. Nullpunkts ir loksnes kreisais apakšējais stūris, frēzējot Z0 ir skārda augšpuse. Pirms lietošanas pārbaudiet programmu uz iekārtas vai NC simulatorā.",
"Jede Achse einzeln: Kante, Ecke, Fläche oder Bohrung anklicken. Nicht gesetzte Achsen kommen vom Rohteilpunkt.":"Katra ass atsevišķi: noklikšķiniet uz malas, stūra, skaldnes vai cauruma. Nenoteiktās asis tiek ņemtas no sagataves punkta.",
"Jede Operation als Unterprogramm (LBL) am Programmende, Aufruf mit CALL LBL":"Katra operācija kā apakšprogramma (LBL) programmas beigās, izsaukums ar CALL LBL",
"Jeder Kreis der Skizze ist ein Bohrungsmittelpunkt. Gebohrt wird entgegen der Skizzennormalen (ins Material).":"Katrs skices aplis ir cauruma centrs. Urbj pretēji skices normālei (materiālā).",
"Jeder Kreis der Skizze wird um die Mitte (in Skizzenkoordinaten) gedreht wiederholt – ein Kreis im Abstand des Teilkreisradius ergibt einen Lochkreis.":"Katrs skices aplis tiek atkārtots, pagriežot ap centru (skices koordinātēs) – aplis soļa riņķa rādiusa attālumā dod urbumu riņķi.",
"Jeder Kreis der Skizze wird zum Raster: Abstände in X und Y der Skizze (auch negativ).":"Katrs skices aplis kļūst par režģi: skices atstarpes pa X un Y (arī negatīvas).",
"Jetzt einen Punkt auf dem zweiten Schenkel.":"Tagad punkts uz otrās malas.",
"Jetzt jede Richtung einmal bis zum Anschlag: schieben, ziehen, drücken, kippen, drehen (10 s) …":"Tagad katrā virzienā vienu reizi līdz galam: bīdīt, vilkt, spiest, sasvērt, griezt (10 s) …",
