"Kalibrieren: einen Abstand größer als 0 angeben.":"Kalibrēšana: norādiet attālumu, kas lielāks par 0.",
"Kalibrieren: ersten Punkt im Bild anklicken (Esc bricht ab).":"Kalibrēšana: uzklikšķiniet uz pirmā punkta attēlā (Esc atceļ).",
"Kalibrieren: wirklicher Abstand der beiden Punkte (mm)":"Kalibrēšana: īstais attālums starp abiem punktiem (mm)",
"Kalibrieren: zwei Punkte im Bild anklicken, deren Abstand bekannt ist, und den wirklichen Abstand eingeben – das Bild bekommt den richtigen Maßstab.":"Kalibrēšana: uzklikšķiniet uz diviem attēla punktiem, kuru attālums ir zināms, un ievadiet īsto attālumu – attēls iegūs pareizo mērogu.",
