"Kante {0}: Lasche an einer gebogenen Kante – ihr Rand wird beim Umformen um {1} % gestaucht (Faltengefahr); der Zuschnitt ist dort eine Näherung.":"Mala {0}: atloks uz liektas malas – tā mala formēšanas laikā tiek saspiesta par {1} % (krokošanās risks); izklājums šeit ir tuvinājums.",
"Kante {0}: Lasche an einer gebogenen Kante – ihr Rand wird beim Umformen um {1} % gestreckt (Rissgefahr); der Zuschnitt ist dort eine Näherung.":"Mala {0}: atloks uz liektas malas – tā mala formēšanas laikā tiek izstiepta par {1} % (plaisāšanas risks); izklājums šeit ir tuvinājums.",
"Kante {0}: das Laschenmaß {1} mm ist kleiner als die Biegung ({2} mm)":"Mala {0}: atloka izmērs {1} mm ir mazāks par locījumu ({2} mm)",
