"Kante {0}: die Lasche kreuzt eine Biegelinie – mit „Abstand Anfang / Ende“ vor der Biegung enden lassen":"Mala {0}: atloks krusto liekuma līniju – ļaujiet tam beigties pirms liekuma, izmantojot „Atstarpe sākums / beigas“",
"Kante {0}: die Lasche liegt in einer Biegezone":"Mala {0}: atloks atrodas liekuma zonā",
"Kante {0}: ein Ausschnitt gehört zu einer Lasche, die es nicht gibt.":"Mala {0}: izgriezums pieder atlokam, kura nepastāv.",
"Kante {0}: ein Ausschnitt in der Lasche liegt {1} mm neben der Biegung (weniger als 2 × Blechdicke) – er verzieht sich beim Biegen.":"Mala {0}: izgriezums atlokā atrodas {1} mm no locījuma (mazāk nekā 2 × skārda biezums) – locīšanas laikā tas deformējas.",
"Kante {0}: ein Ausschnitt liegt {1} mm neben der Biegung (weniger als 2 × Blechdicke) – er verzieht sich beim Biegen.":"Mala {0}: izgriezums atrodas {1} mm no locījuma (mazāk par 2 × skārda biezums) – locīšanas laikā tas deformēsies.",
"Kante {0}: ein Ausschnitt ragt über die Lasche hinaus.":"Mala {0}: izgriezums sniedzas ārpus atloka.",
"Kante {0}{1}: Lasche {2} mm ist kürzer als 2 × Blechdicke – auf der Abkantpresse kaum zu biegen.":"Mala {0}{1}: atloks {2} mm ir īsāks par 2 × skārda biezums – uz lokpreses gandrīz nav saliecams.",
