"Kappe loslassen und „Nullpunkt kalibrieren“ wählen. Danach jede Richtung ausprobieren: der Balken soll sich bewegen, in Ruhe in der grauen Totzone bleiben.":"Atlaidiet vāciņu un izvēlieties „Kalibrēt nullpunktu“. Pēc tam izmēģiniet katru virzienu: joslai jākustas, miera stāvoklī tai jāpaliek pelēkajā mirušajā zonā.",
"Kappe schieben = verschieben, drücken/ziehen = zoomen, kippen und drehen = Modell drehen. In Skizzen nur Verschieben und Zoomen. SpaceMouse Pro/Enterprise: T, F, R = Ansicht oben, vorne, rechts. Falls nichts passiert: 3Dconnexion-Treiber kurz beenden und neu verbinden.":"Bīdīt vāciņu = pārbīdīt, spiest/vilkt = tuvināt/tālināt, sasvērt un pagriezt = griezt modeli. Skicēs tikai pārbīde un tālummaiņa. SpaceMouse Pro/Enterprise: T, F, R = skats no augšas, no priekšas, no labās puses. Ja nekas nenotiek: uz brīdi aizveriet 3Dconnexion draiveri un pievienojiet no jauna.",
