"Kontur mit {0} Punkten – Okuma: G85 (LAP) mit Kontur G81…G80, Fanuc: G71 P…Q…. Die Steuerung schruppt mit ihrer eigenen Aufteilung; die Simulation hier ist die WerkFab-Bahn.":"Kontūra ar {0} punktiem – Okuma: G85 (LAP) ar kontūru G81…G80, Fanuc: G71 P…Q…. Vadība veic rupjapstrādi ar savu sadalījumu; simulācija šeit ir WerkFab trajektorija.",
