"Konturen außen und innen":"Ārējās un iekšējās kontūras",
"Konturen folgen dem Rand der dunklen Flächen. Die Mittellinie läuft in der Mitte der Striche – passend für Gravuren und Strichzeichnungen. „Geraden, Bögen und Kreise“ erkennt gerade Kanten, scharfe Ecken, Rundungen und Kreise; „Linienzüge“ folgt dem Bild Punkt für Punkt. Den Maßstab danach bei Bedarf mit „Vorlage kalibrieren“ oder „Skalieren“ anpassen.":"Kontūras seko tumšo laukumu malai. Viduslīnija iet pa triepienu vidu – piemērota gravējumiem un līniju zīmējumiem. „Taisnes, loki un apļi“ atpazīst taisnas malas, asus stūrus, noapaļojumus un apļus; „Lauztās līnijas“ seko attēlam punkts pa punktam. Pēc tam mērogu vajadzības gadījumā pielāgojiet ar „Kalibrēt šablonu“ vai „Mērogot“.",
"Konturen mit Radiuskorrektur an der Steuerung (RL/RR) fahren mit APPR/DEP an und ab; die Steuerung berechnet Hilfspunkt und Korrektur selbst":"Kontūras ar rādiusa korekciju vadības sistēmā (RL/RR) tiek pievirzītas un atvirzītas ar APPR/DEP; vadības sistēma pati aprēķina palīgpunktu un korekciju",
