"Kurven":"Līknes",
"Kurven einer Skizze auf der Planfläche (quer zur Drehachse) mit einem angetriebenen Fräser entlang Z (X und C fahren gemeinsam; Fanuc: Polar-Interpolation G12.1). Offene Kurven werden hin und zurück gefräst. Tiefe ab Planfläche.":"Skices līknes uz priekšgala virsmas (šķērsām griešanās asij) ar dzīvo frēzi gar Z (X un C kustas kopā; Fanuc: polārā interpolācija G12.1). Atvērtās līknes frēzē turp un atpakaļ. Dziļums no priekšgala virsmas.",
"Kurven einer Skizze, die längs zur Drehachse liegt, werden auf den Umfang gewickelt und mit einem angetriebenen Fräser gefräst, der zur Achse zeigt (Z und C fahren gemeinsam; Fanuc: Zylinder-Interpolation G7.1). Die Skizzenebene bestimmt den Winkel, an dem die Kontur sitzt; waagerechte Strecken in der Skizze werden Bögen um das Teil. Tiefe ab Außendurchmesser.":"Skices līknes, kas atrodas gar griešanās asi, tiek uztītas uz apkārtmēra un frēzētas ar dzīvo frēzi, kas vērsta pret asi (Z un C kustas kopā; Fanuc: cilindriskā interpolācija G7.1). Skices plakne nosaka leņķi, kurā atrodas kontūra; horizontāli nogriežņi skicē kļūst par lokiem ap detaļu. Dziļums no ārējā diametra.",
"Kurzbefehl":"Īsinājumtaustiņš",
"Kurze Wege (bis zum Halteabstand) fährt das Werkzeug unten im Übergangsvorschub statt über die Rückzugshöhe – ohne Kollisionsprüfung, daher klein halten.":"Īsus ceļus (līdz noturēšanas attālumam) instruments veic apakšā ar pārejas padevi, nevis caur atvilkšanas augstumu – bez sadursmju pārbaudes, tāpēc turiet mazu.",
