"Material im Setup unter „Rohteil → Rohteilmaterial“ wählen. Die Dichte ergibt das Rohteilgewicht, Vc ist ein Richtwert für Hartmetall; die Farbe zeigt die Simulation.":"Izvēlieties materiālu uzstādīšanā sadaļā „Sagatave → Sagataves materiāls“. Blīvums nosaka sagataves svaru, Vc ir orientējoša vērtība cietsakausējumam; krāsu parāda simulācija.",
