"Materialien über „Darstellung“ (A) auf die Körper ziehen. Beim In-Canvas-Rendern wird das Bild mit jedem Durchgang glatter (weiche Schatten, saubere Kanten); jede Kamerabewegung beginnt neu.":"Velciet materiālus uz ķermeņiem, izmantojot „Attēlojums“ (A). Vizualizējot skatā, attēls ar katru caurlaidi kļūst gludāks (mīkstas ēnas, tīras malas); katra kameras kustība sāk no jauna.",
