"Mehrere Schlichtdurchgänge":"Vairāki apdares gājieni",
"Mehrere aneinanderhängende Kanten zählen als eine Strecke: Der Radius läuft vom Anfang der Kette bis zu ihrem Ende, Stützpunkte gelten in % der ganzen Kettenlänge. Das rechnet der große Geometriekern.":"Vairākas savienotas malas tiek uzskatītas par vienu posmu: rādiuss iet no ķēdes sākuma līdz tās beigām, atbalsta punkti tiek doti % no visa ķēdes garuma. To aprēķina pilnais ģeometrijas kodols.",
