"Mit Stützpunkten läuft der Radius durch die angegebenen Werte (Lage in % der Kantenlänge). Das rechnet der große Geometriekern; beim ersten Mal lädt er einige Sekunden.":"Ar atbalsta punktiem rādiuss iet cauri norādītajām vērtībām (novietojums % no malas garuma). To aprēķina pilnais ģeometrijas kodols; pirmo reizi tas ielādējas dažas sekundes.",
"Mit dem 3D-Taster kann nicht zerspant werden":"Ar 3D taustiņu nevar apstrādāt ar skaidošanu",
"Mit dem Fertigteil vergleichen: grün = auf Maß, blau = Restmaterial, rot = zu tief":"Salīdzināt ar gatavo detaļu: zaļš = atbilst izmēram, zils = atlikušais materiāls, sarkans = pārāk dziļi",
"Mit der Maus neben eine Kontur fahren (die Seite bestimmt die Richtung) · Esc beendet":"Virziet peli blakus kontūrai (puse nosaka virzienu) · Esc beidz",
"Mit diesem Werkzeug kann nicht gefräst werden":"Ar šo instrumentu nevar frēzēt",
"Mit einem Gewindebohrer nur Zyklus „Gewindebohren“ – ein Bohrzyklus würde ihn abbrechen":"Ar vītņu griezēju izmantojiet tikai ciklu “Vītņu griešana” — urbšanas cikls to nolauztu",
"Mit mehreren Zustellungen wird die Gewindetiefe in Schritten gefräst, die jeweils etwa gleich viel abnehmen – schont kleine Gewindefräser und harte Werkstoffe. Der Leerdurchgang fährt die letzte Bahn noch einmal ohne Zustellung.":"Ar vairākām padevēm vītnes dziļums tiek frēzēts soļos, kuros katrā noņem aptuveni vienādu materiāla daudzumu – saudzē mazas vītņu frēzes un cietus materiālus. Tukšais gājiens vēlreiz izbrauc pēdējo trajektoriju bez padeves.",
"Mit „Bohrzyklen“ im NC-Programm werden Steuerungszyklen ausgegeben (G81–G86, Heidenhain CYCL 200–207, Sinumerik CYCLE81–85), sonst ausgeschriebene Bewegungen.":"Ar „Urbšanas cikliem“ NC programmā tiek izvadīti vadības cikli (G81–G86, Heidenhain CYCL 200–207, Sinumerik CYCLE81–85), pretējā gadījumā – izvērstas kustības.",
"Mit „Original behalten“ werden Original und Spiegelbild ein Netz; Punkte auf der Spiegelebene werden verbunden – aus einer offenen Hälfte wird so ein geschlossenes Teil.":"Ar „Paturēt oriģinālu” oriģināls un spoguļattēls kļūst par vienu tīklu; punkti uz spoguļa plaknes tiek savienoti – no atvērtas puses tā rodas slēgta detaļa.",
