"Nur das bearbeiten, was ein größerer Fräser in Ecken stehen gelassen hat.":"Apstrādāt tikai to, ko lielāka frēze atstājusi stūros.",
"Nur die Stellen der Kontur nachfahren, die ein größerer Fräser nicht erreicht hat (Innenecken, enge Stellen). Ohne An-/Abfahrbögen, Haltestege und Schlichtdurchgänge; Korrektur im Rechner.":"Pārbraukt tikai tās kontūras vietas, kurām lielāka frēze netika klāt (iekšējie stūri, šaurās vietas). Bez pieejas/atiešanas lokiem, turētājstieņiem un tīrapstrādes gājieniem; korekcija datorā.",
"Nur dort, wo das Referenzwerkzeug nicht hinkam: flache Bereiche parallel, steile Bereiche als Wasserlinie. Mit einem Werkzeug aus der Liste zählt dessen Form mit – zum Beispiel was ein Torusfräser in den Hohlkehlen stehen lässt.":"Tikai tur, kur atsauces instruments netika klāt: plakanos apgabalus paralēli, stāvos kā ūdenslīniju. Ar instrumentu no saraksta tiek ņemta vērā arī tā forma – piemēram, ko torusa frēze atstāj ieliekumos.",
"Nur ebene Flächen können als Skizzenebene dienen.":"Skices plaknei var kalpot tikai plakanas skaldnes.",
