"Nur ebene Flächen lassen sich ersetzen":"Nomainīt var tikai plakanas skaldnes",
"Nur ebene Flächen und Zylinderflächen (Bohrungen, Zapfen) lassen sich versetzen":"Nobīdīt var tikai plakanas un cilindriskas skaldnes (caurumus, tapas)",
"Nur ebene Flächen, die nach oben zum Werkzeug zeigen (waagerecht in diesem Setup).":"Tikai plakanas skaldnes, kas vērstas uz augšu pret instrumentu (horizontālas šajā uzstādīšanā).",
"Nur für Außen-Drehmeißel":"Tikai ārējiem virpas tēraudiem",
