"Nut":"Rieva",
"Nut angetrieben":"Rieva ar dzinēju",
"Nut angetrieben (C-Achse)":"Rieva ar dzinēju (C ass)",
"Nut liegt nicht am Teil":"Rieva neatrodas uz detaļas",
"Nut längs der Drehachse (z. B. Passfedernut) mit einem angetriebenen Fräser, der zur Achse zeigt; die Hauptspindel hält das Teil als C-Achse. Nutbreite = Fräser-Ø. Start/Ende Z in Modell-Z; reicht die Nut bis zur Planfläche, fährt der Fräser von vorn ein, sonst taucht er am Start ein. Tiefe ab Außendurchmesser.":"Rieva gar griešanās asi (piem., ķīļa rieva) ar dzīvo frēzi, kas vērsta pret asi; galvenā vārpsta tur detaļu kā C asi. Rievas platums = frēzes Ø. Sākums/beigas Z modeļa Z; ja rieva sniedzas līdz priekšgala virsmai, frēze ieiet no priekšpuses, citādi iegrimst sākumā. Dziļums no ārējā diametra.",
