"Offene Kanten werden rot angezeigt. „Reparieren“ schließt Löcher.":"Atvērtās malas tiek rādītas sarkanā krāsā. „Labot“ aizver caurumus.",
"Offene Linie in einer Skizze wählen":"Izvēlieties atvērtu līniju skicē",
"Offene oder geschlossene Kurven werden senkrecht zur Skizze gezogen – es entsteht eine Fläche (Wand ohne Dicke). Mit „Aufdicken“ oder „Zusammenfügen“ wird daraus ein Volumen.":"Atvērtas vai slēgtas līknes tiek izvilktas perpendikulāri skicei – rezultāts ir virsma (siena bez biezuma). Ar „Sabiezināt“ vai „Sašūt“ no tās iegūst tilpumu.",
"Offene oder geschlossene Kurven werden um die Achse gedreht – es entsteht eine Fläche, kein Volumen.":"Atvērtas vai slēgtas līknes tiek pagrieztas ap asi – rezultāts ir virsma, nevis tilpums.",
"Ohne eigene Taste gilt der Standard „{0}“.":"Bez pielāgota taustiņa tiek izmantots noklusējuma „{0}“.",
"Ohne „Modelliert“ wird das Gewinde nur dargestellt (schnell). Modelliert wird die Gewindeform wirklich ausgeschnitten, z. B. für 3D-Druck. Bohrung für M8 = Ø6,8.":"Bez „Modelēta“ vītne tikai tiek attēlota (ātri). Modelējot vītnes forma tiek patiešām izgriezta, piem., 3D drukai. Caurums M8 = Ø6,8.",
"Okuma OSP Drehen":"Okuma OSP virpošana",
"Okuma OSP-M Fräsen":"Okuma OSP-M frēzēšana",
"Okuma OSP: G28/G53 fahren dort nicht auf Maschinenkoordinaten (G53 hebt die Werkzeuglängenkorrektur auf) – Rückzug auf Sicherheitshöhe, keine XY-Referenzfahrt ausgegeben":"Okuma OSP: G28/G53 tur nepārvietojas uz iekārtas koordinātām (G53 atceļ instrumenta garuma korekciju) – atvilkšana uz drošības augstumu, XY references kustība netiek izvadīta",
"Okuma OSP: keine Glättungsfunktion ausgegeben (G5.1 ist Fanuc) – Hi-Cut/Super-NURBS an der Maschine einstellen":"Okuma OSP: izlīdzināšanas funkcija netiek izvadīta (G5.1 ir Fanuc) – iestatiet Hi-Cut/Super-NURBS iekārtā",
"Okuma: Korrektur+Werkzeug+Schneide (z. B. 010101)":"Okuma: korekcija+instruments+asmens (piem., 010101)",
"OpenCascade (alle Funktionen)":"OpenCascade (visas funkcijas)",
"OpenCascade: alle Funktionen. Rust-Kern (truck, experimentell): Grundkörper, Extrusion, Rotation, Bohrung, Muster, Spiegeln, Verschieben, Skalieren, Kombinieren und STEP-Export – andere Features werden als „noch nicht unterstützt“ markiert.":"OpenCascade: visas funkcijas. Rust kodols (truck, eksperimentāls): pamatķermeņi, izspiešana, rotācija, caurums, masīvs, spogulēšana, pārvietošana, mērogošana, apvienošana un STEP eksports – citi elementi tiek atzīmēti kā „vēl neatbalstīti”.",
