"Positiv = nach außen (mehr Material), negativ = nach innen. Ebene Flächen verschieben sich; bei einer Bohrung oder einem Zapfen ändert sich der Radius um den Abstand – eine Bohrung wird mit positivem Abstand enger.":"Pozitīvs = uz āru (vairāk materiāla), negatīvs = uz iekšu. Plakanās skaldnes pārvietojas; caurumam vai tapai rādiuss mainās par attālumu – caurums ar pozitīvu attālumu kļūst šaurāks.",
