"Prägung: die Kontur wird nicht ausgeschnitten, sondern um die Höhe aus der Platte gedrückt. Senkprägung: der Rand einer runden Bohrung wird zu einem 90°-Kegel gedrückt – für Senkschrauben in dünnem Blech (− nach unten: Schraube von oben).":"Reljefs: kontūra netiek izgriezta, bet izspiesta no plātnes par norādīto augstumu. Konisks iespiedums: apaļa cauruma mala tiek iespiesta 90° konusā – skrūvēm ar slēpto galvu plānā skārdā (− uz leju: skrūve no augšas).",
