"Tasche auf dem Umfang aus den geschlossenen Konturen einer Skizze, die längs zur Drehachse liegt (innere Konturen bleiben als Inseln stehen). Die Skizze wird auf den Durchmesser gewickelt; ein angetriebener Schaftfräser, der zur Achse zeigt, räumt von innen nach außen (Z und C fahren gemeinsam; Fanuc: Zylinder-Interpolation G7.1). Der Fräser taucht auf einer Rampe entlang des innersten Rings ein.":"Kabata uz apkārtmēra no skices slēgtajām kontūrām, kas atrodas gar griešanās asi (iekšējās kontūras paliek kā saliņas). Skice tiek uztīta uz diametra; dzenama kātfrēze, kas vērsta pret asi, izņem materiālu no iekšpuses uz āru (Z un C pārvietojas kopā; Fanuc: cilindriskā interpolācija G7.1). Frēze ieurbjas pa rampu gar visiekšējo gredzenu.",
"Tasche in der Planfläche aus den geschlossenen Konturen einer Skizze (innere Konturen bleiben als Inseln stehen), mit einem angetriebenen Schaftfräser entlang Z. Geräumt wird von innen nach außen; der Fräser taucht auf einer Rampe entlang der innersten Bahn ein und bleibt innerhalb einer Ebene unten. X und C fahren gemeinsam (Fanuc: Polar-Interpolation G12.1). Tiefe ab Planfläche.":"Kabata priekšgala virsmā no skices slēgtajām kontūrām (iekšējās kontūras paliek kā salas) ar dzīvo kātfrēzi gar Z. Izfrēzē no iekšpuses uz āru; frēze iegrimst pa rampu gar iekšējo trajektoriju un viena līmeņa ietvaros paliek apakšā. X un C kustas kopā (Fanuc: polārā interpolācija G12.1). Dziļums no priekšgala virsmas.",
