"Vernetzung fehlgeschlagen:":"Tīklošana neizdevās:",
"Verrechnet zwei geschlossene Netze wirklich miteinander: innen liegende Flächen verschwinden, die Schnittkanten werden neu vernetzt. Gerechnet wird nur dort, wo sich die beiden Netze begegnen können – ein großes Netz mit einem kleinen Eingriff geht deshalb schnell. Überlappen zwei große Netze ganz, vorher „Reduzieren“.":"Patiešām savstarpēji aprēķina divus slēgtus tīklus: iekšpusē esošās skaldnes pazūd, griezuma malas tiek no jauna sadalītas tīklā. Aprēķins notiek tikai tur, kur abi tīkli var satikties – tāpēc liels tīkls ar nelielu iejaukšanos tiek apstrādāts ātri. Ja divi lieli tīkli pilnībā pārklājas, vispirms „Samazināt”.",
