"Wickelt die Skizzenkurven auf den Zylinder: X bleibt X, der Abstand quer zur Achse wird zum Bogen auf dem Abwicklungs-Ø (Drehung A). Die Skizze muss parallel zur A-Achse liegen, z. B. auf einer Tangentialebene. Gefräst wird in fester Tiefe unter der Teiloberfläche – für Gravuren, Schriften und Nuten rund um das Teil.":"Uztin skices līknes uz cilindra: X paliek X, attālums šķērsām asij kļūst par loku uz attīšanas Ø (rotācija A). Skicei jābūt paralēlai A asij, piem., pieskares plaknē. Frēzē nemainīgā dziļumā zem detaļas virsmas – gravējumiem, uzrakstiem un rievām ap detaļu.",
