"„Ineinander schachteln“ legt die Zuschnitte in die Lücken und Buchten ihrer Nachbarn und in deren Ausschnitte (ohne 90°-Drehen nur um 180° gewendet); der Abstand wird nie unterschritten. Ohne den Haken liegen sie nach ihrem umschließenden Rechteck in Reihen. Mit „Skizze + Körper“ entstehen flache Körper in Blechdicke, die sich in der Fertigung mit 2D-Kontur ausschneiden lassen.":"„Ievietot vienu otrā” izliek sagataves kaimiņu spraugās un līčos un to izgriezumos (bez pagriešanas par 90° tikai apgrieztas par 180°); atstarpe nekad netiek samazināta. Bez atzīmes tās atrodas rindās pēc ietverošā taisnstūra. Ar „Skice + ķermeņi” rodas plakani ķermeņi skārda biezumā, ko ražošanā var izgriezt ar 2D kontūru.",
"„Innen/Außen“ braucht geschlossene Konturen – offene Kurven mit „Auf der Kurve“ fräsen":"“Iekšā/ārā” prasa slēgtas kontūras — atvērtas līknes frēzējiet ar “Uz līknes”",
"„Skizze fertig“ → Extrusion, Rotation oder Bohrung.":"„Skice pabeigta“ → Izspiešana, Rotācija vai Caurums.",
"„Skizze“ → Ebene XY/XZ/YZ wählen oder eine ebene Fläche anklicken.":"„Skice“ → izvēlieties plakni XY/XZ/YZ vai noklikšķiniet uz plakanas skaldnes.",
