"⚠ Programmlogik (JavaScript) wird nicht ausgeführt: Sonderfunktionen, 4./5. Achse, Messzyklen und Maschinenoptionen bitte im Postprozessor-Editor prüfen.":"⚠ Programmas loģika (JavaScript) netiek izpildīta: īpašās funkcijas, 4./5. ass, mērīšanas cikli un iekārtas opcijas lūdzu pārbaudiet postprocesora redaktorā.",
